1	import React, { useId } from 'react';
2	import { chakra, Drawer, DrawerOverlay, useMultiStyleConfig, useModalContext, ModalFocusScope } from '@chakra-ui/react';
3	import type { SystemStyleObject } from '@chakra-ui/react';
4	import { motion } from 'framer-motion';
5	import { ZimmButton } from 'app/components/ui-kits/atoms/zimmButton';
6	
7	const ZIMM_DRAWER_RECIPE = 'ZimmDrawer';
8	
9	// framer-motion's `Transition.ease` wants a literal, mutable 4-tuple (`BezierDefinition`) — a
10	// plain array literal infers as `number[]`, and `as const` infers a *readonly* tuple, neither of
11	// which satisfies it, hence the explicit cast.
12	const BEZIER_SLIDES_EASING = [0.87, 0, 0.13, 1] as [number, number, number, number];
13	// Mirrors theme/foundation/motion.ts's `duration.default` (300ms) and `easing.slides`
14	// (cubic-bezier(0.87, 0, 0.13, 1), "panels and overlays entering the screen") — hand-converted
15	// to framer-motion's shape (seconds, not ms; a bezier tuple, not a CSS `cubic-bezier()` string)
16	// since motion.ts's tokens are CSS-string form and framer-motion doesn't accept that form. One
17	// shared value for both enter and exit — that symmetry is the whole point (SFCC-898).
18	const DRAWER_TRANSITION = { duration: 0.3, ease: BEZIER_SLIDES_EASING };
19	
20	// `motion(chakra.div)` — framer OUTSIDE, chakra INSIDE. This ordering matters: framer's
21	// `motion()` only intercepts its own known animation props (initial/animate/exit/transition/
22	// variants) and forwards everything else straight to the wrapped component, so `transition`
23	// reaches framer-motion directly here. Chakra's OWN internal Drawer does the reverse
24	// (`chakra(Slide)`) — chakra wraps the animated component — and chakra's `shouldForwardProp`
25	// treats any prop literally named `transition` as a CSS shorthand style prop (it's a real
26	// Chakra/styled-system prop name), silently swallowing it before it ever reaches the wrapped
27	// component's real props (confirmed directly in @chakra-ui/system's should-forward-prop.js).
28	// That's why `<DrawerContent transition={...}>` had no effect and why this file no longer uses
29	// Chakra's `<DrawerContent>` at all — SFCC-898's close-animation defect (asymmetric enter/exit;
30	// Chakra's own Slide defaults to a spring-physics enter vs. a fixed 150ms tween exit, per
31	// @chakra-ui/transition's slide.js) can't be fixed through any prop that component exposes.
32	const MotionChakraDiv = motion(chakra.div);
33	
34	// Matches Figma's own named drawer sizes exactly (SFCC-898) — see zimmDrawer.css.ts's
35	// file-level comment for the width/usage table. `xLarge` has no consumer yet (Cart is a full
36	// page today, not a drawer).
37	export type ZimmDrawerSize = 'large' | 'tablet' | 'small' | 'xLarge' | 'mobile';
38	
39	type ZimmDrawerBaseProps = {
40	  /** Whether the drawer is open. */
41	  isOpen: boolean;
42	  /** Called on backdrop click, Escape, and the close button (all via Chakra's Drawer). */
43	  onClose: () => void;
44	  /** Desktop/tablet width variant — see ZimmDrawerSize. Collapses to the mobile treatment
45	   *  below the tablet breakpoint regardless of which value is chosen — see zimmDrawer.css.ts. */
46	  size: ZimmDrawerSize;
47	  children: React.ReactNode;
48	  /** Text style for the title. 'large' applies heading1 (24px, uppercase, Futura Round regular);
49	   *  'small' applies body2Strong (14px bold). Defaults to 'large'. Only relevant when `title`
50	   *  is provided. */
51	  titleStyle?: 'large' | 'small';
52	  /** Element to focus when the drawer closes. Use when the trigger may not have received
53	   *  keyboard focus before opening (e.g. mouse click) — without this Chakra falls back to
54	   *  document.body and AC10 focus-return fails. */
55	  finalFocusRef?: React.RefObject<HTMLElement>;
56	  /** Element to focus when the drawer opens. Overrides Chakra's default (first focusable element
57	   *  in the panel, usually the close button) — use to land focus directly on the primary input. */
58	  initialFocusRef?: React.RefObject<HTMLElement>;
59	  /** Whether to render the semi-transparent dark overlay behind the drawer. Defaults to true.
60	   *  Pass false for drawers that overlay a page the user still needs to see (e.g. the PLP
61	   *  filter drawer, where keeping the product grid visible aids orientation). */
62	  hasOverlay?: boolean;
63	};
64	
65	/**
66	 * Exactly one of:
67	 * - `title`       — renders an inline header row (title left, close button right); the drawer's
68	 *                   accessible name is derived from the rendered title element automatically.
69	 * - `labelledBy`  — ID of an existing element that labels the drawer (e.g. ZimmPdpDrawer's own
70	 *                   tab header). Paired with the floating close button.
71	 * - `aria-label`  — explicit string label when neither a visible title nor a separate element
72	 *                   is available.
73	 */
74	type ZimmDrawerProps = ZimmDrawerBaseProps &
75	  (
76	    | { title: string; labelledBy?: never; 'aria-label'?: never }
77	    | { title?: never; labelledBy: string; 'aria-label'?: never }
78	    | { title?: never; labelledBy?: never; 'aria-label': string }
79	  );
80	
81	// Deliberately not named `ZimmDrawerContentProps` — scripts/generateRegistry.mjs's
82	// extractTsProps merges every `*Props`-suffixed type in a file into one component's registry
83	// row when it can't isolate the preferred one (ZimmDrawerProps' multi-line union body isn't
84	// matched by its regex, which can't cross a newline — a documented limitation, not a bug to
85	// patch there). That merge was leaking this internal helper's own fields (ariaLabel,
86	// contentStyles, closeButtonStyles) into ZimmDrawer's public registry entry.
87	type ZimmDrawerContentConfig = {
88	  children: React.ReactNode;
89	  onClose: () => void;
90	  /** Renders an inline header row (title left, close button right) instead of the floating
91	   *  close button when provided — see ZimmDrawerProps' `title` member. */
92	  title?: string;
93	  titleId?: string;
94	  titleStyle?: 'large' | 'small';
95	  labelledBy?: string;
96	  ariaLabel?: string;
97	  contentStyles: SystemStyleObject;
98	  headerStyles: SystemStyleObject;
99	  headerTitleStyles: SystemStyleObject;
100	  closeButtonStyles: SystemStyleObject;
101	};
102	
103	/**
104	 * Replaces Chakra's own `<DrawerContent>` — see the `MotionChakraDiv` comment above for why.
105	 * Reuses Chakra's real dialog/focus/aria mechanics directly (`useModalContext`,
106	 * `ModalFocusScope` — both genuinely public exports, not reaching into Chakra internals) so
107	 * focus trap, initial focus, focus restore, body-scroll lock, and Escape/overlay-click-to-close
108	 * all still come from Chakra exactly as before; only the slide transition itself is now ours.
109	 *
110	 * Renders either an inline title row (title left, close button right) when `title` is passed, or
111	 * a floating close button only — see ZimmDrawer's own docblock for when each is used.
112	 *
113	 * @param props see ZimmDrawerContentConfig
114	 */
115	const ZimmDrawerContent = ({
116	  children,
117	  onClose,
118	  title,
119	  titleId,
120	  titleStyle = 'large',
121	  labelledBy,
122	  ariaLabel,
123	  contentStyles,
124	  headerStyles,
125	  headerTitleStyles,
126	  closeButtonStyles,
127	}: ZimmDrawerContentConfig) => {
128	  const { getDialogProps, getDialogContainerProps } = useModalContext();
129	  const dialogProps = getDialogProps({ 'aria-label': ariaLabel });
130	  // getDialogProps always computes `aria-labelledby` from Chakra's own <DrawerHeader> mount
131	  // state, which ZimmDrawer never renders (no header sub-component in this tree) — so it
132	  // always resolves to undefined regardless of what's passed in above. Set it directly so the
133	  // `title` and `labelledBy` prop variants of ZimmDrawerProps actually work.
134	  if (title && titleId) {
135	    dialogProps['aria-labelledby'] = titleId;
136	  } else if (labelledBy) {
137	    dialogProps['aria-labelledby'] = labelledBy;
138	  }
139	  const containerProps = getDialogContainerProps();
140	
141	  return (
142	    <ModalFocusScope>
143	      <chakra.div {...containerProps} __css={{ position: 'fixed', inset: 0, display: 'flex', zIndex: 'modal' }}>
144	        <MotionChakraDiv
145	          {...dialogProps}
146	          initial={{ x: '100%' }}
147	          animate={{ x: 0 }}
148	          exit={{ x: '100%' }}
149	          transition={DRAWER_TRANSITION}
150	          __css={{ position: 'fixed', top: 0, right: 0, bottom: 0, outline: 0, ...contentStyles }}
151	        >
152	          {title ? (
153	            <chakra.div sx={headerStyles}>
154	              <chakra.span
155	                id={titleId}
156	                sx={headerTitleStyles}
157	                textStyle={titleStyle === 'small' ? 'body2Strong' : 'heading1'}
158	              >
159	                {title}
160	              </chakra.span>
161	              <ZimmButton variant="icon" icon="close" label="Close" onClick={onClose} />
162	            </chakra.div>
163	          ) : (
164	            <chakra.div sx={closeButtonStyles}>
165	              <ZimmButton variant="icon" icon="close" label="Close" onClick={onClose} />
166	            </chakra.div>
167	          )}
168	          {children}
169	        </MotionChakraDiv>
170	      </chakra.div>
171	    </ModalFocusScope>
172	  );
173	};
174	
175	/**
176	 * Generic right-anchored slide-in drawer shell — overlay, panel, and a Figma-matched size
177	 * variant (see ZimmDrawerSize), built on Chakra's Drawer primitive (focus trap, initial focus,
178	 * focus restore, body-scroll lock, and Escape/overlay-click-to-close all come from Chakra, not
179	 * hand-rolled).
180	 *
181	 * Pass `title` to render an inline header row (title text left, close button right) sized per the
182	 * Figma drawer/header frames. Omit `title` and pass `labelledBy`/`aria-label` instead for drawers
183	 * that supply their own header (e.g. ZimmPdpDrawer's tab row), which keeps the floating close
184	 * button behaviour.
185	 *
186	 * @param props see ZimmDrawerProps
187	 */
188	export const ZimmDrawer = (props: ZimmDrawerProps) => {
189	  const {
190	    isOpen,
191	    onClose,
192	    size,
193	    children,
194	    titleStyle = 'large',
195	    finalFocusRef,
196	    initialFocusRef,
197	    hasOverlay = true,
198	  } = props;
199	  const styles = useMultiStyleConfig(ZIMM_DRAWER_RECIPE, { variant: size });
200	  const titleId = useId();
201	
202	  const title = 'title' in props ? props.title : undefined;
203	  const labelledBy = !title && 'labelledBy' in props ? props.labelledBy : undefined;
204	  const ariaLabel = !title && 'aria-label' in props ? props['aria-label'] : undefined;
205	
206	  // Chakra's FocusLock remains active during the exit animation, so any focus call made
207	  // while the drawer is still mounted (rAF, close-button onClick) gets trapped and dropped.
208	  // onCloseComplete fires after the animation finishes and FocusLock is released — the only
209	  // reliable moment to restore focus. Covers both close-button click and Escape for all
210	  // consumers that pass finalFocusRef.
211	  const handleCloseComplete = () => {
212	    if (finalFocusRef) finalFocusRef.current?.focus();
213	  };
214	
215	  return (
216	    <Drawer
217	      isOpen={isOpen}
218	      onClose={onClose}
219	      placement="right"
220	      onCloseComplete={handleCloseComplete}
221	      initialFocusRef={initialFocusRef}
222	    >
223	      {hasOverlay && <DrawerOverlay sx={styles.overlay} />}
224	      {/* aria-labelledby (not aria-label) for the title case: Chakra's own <DrawerContent>
225	          would clobber it with its own headingId (undefined without a DrawerHeader), but
226	          ZimmDrawerContent bypasses <DrawerContent> entirely and sets dialogProps itself
227	          (see its own comment above) — the clobbering bug this would otherwise work around
228	          doesn't apply here, so referencing the visible title node is safe and preferred. */}
229	      <ZimmDrawerContent
230	        onClose={onClose}
231	        title={title}
232	        titleId={title ? titleId : undefined}
233	        titleStyle={titleStyle}
234	        labelledBy={labelledBy}
235	        ariaLabel={ariaLabel}
236	        contentStyles={styles.content}
237	        headerStyles={styles.header}
238	        headerTitleStyles={styles.headerTitle}
239	        closeButtonStyles={styles.closeButton}
240	      >
241	        {children}
242	      </ZimmDrawerContent>
243	    </Drawer>
244	  );
245	};
246

1	import React, { useState } from 'react';
2	import type { Meta, StoryObj } from '@storybook/react-webpack5';
3	import { chakra } from '@chakra-ui/react';
4	import { expect, userEvent, waitForElementToBeRemoved, within } from 'storybook/test';
5	import { ZimmDrawer } from './index';
6	import type { ZimmDrawerSize } from './index';
7	
8	const meta: Meta<typeof ZimmDrawer> = {
9	  title: 'Elements/ZimmDrawer',
10	  component: ZimmDrawer,
11	};
12	export default meta;
13	type Story = StoryObj<typeof ZimmDrawer>;
14	
15	/**
16	 * Generic chrome only — no tab/header content here (see Commerce/ZimmPdpDrawer for a real
17	 * consumer). Proves the shell renders with the expected dialog semantics at each size variant.
18	 */
19	// Named component rather than an inline `render: () => { useState(...) }` — see zimmModal's
20	// story for why a lowercase `render` can't call hooks directly.
21	const OpenDrawerExample = ({ size }: { size: ZimmDrawerSize }) => {
22	  const [isOpen, setIsOpen] = useState(true);
23	  return (
24	    <ZimmDrawer isOpen={isOpen} onClose={() => setIsOpen(false)} size={size} aria-label="Example drawer">
25	      <chakra.p padding="var(--zimm-scale-xl)">Generic ZimmDrawer chrome with arbitrary children.</chakra.p>
26	    </ZimmDrawer>
27	  );
28	};
29	
30	export const Large: Story = {
31	  render: () => <OpenDrawerExample size="large" />,
32	  play: async () => {
33	    // Portal renders outside canvasElement — testing.md §Layer-2 exception. Chakra's Drawer is
34	    // built on its Modal primitive, which renders DrawerContent via a Portal by default, so
35	    // within(canvasElement) can't reach it.
36	    const doc = within(document.body);
37	    const dialog = await doc.findByRole('dialog');
38	    await expect(dialog).toBeInTheDocument();
39	    await expect(dialog).toHaveAttribute('aria-label', 'Example drawer');
40	  },
41	};
42	
43	export const Tablet: Story = {
44	  render: () => <OpenDrawerExample size="tablet" />,
45	};
46	
47	export const Small: Story = {
48	  render: () => <OpenDrawerExample size="small" />,
49	};
50	
51	export const XLarge: Story = {
52	  render: () => <OpenDrawerExample size="xLarge" />,
53	};
54	
55	export const Mobile: Story = {
56	  render: () => <OpenDrawerExample size="mobile" />,
57	};
58	
59	export const CloseButtonClosesTheDrawer: Story = {
60	  render: () => <OpenDrawerExample size="large" />,
61	  play: async () => {
62	    // Portal renders outside canvasElement — testing.md §Layer-2 exception (see Large's play).
63	    const doc = within(document.body);
64	    const dialog = await doc.findByRole('dialog');
65	    await expect(dialog).toBeInTheDocument();
66	
67	    await userEvent.click(doc.getByRole('button', { name: /close/i }));
68	
69	    // Chakra's Drawer plays a slide-out exit transition (framer-motion) before AnimatePresence
70	    // actually unmounts the dialog node — an immediate `queryByRole('dialog')` assertion here
71	    // catches it mid-animation, still present with a near-100% translateX. Wait for the real
72	    // removal instead of asserting the instant after the click.
73	    await waitForElementToBeRemoved(dialog);
74	  },
75	};
76	
77	// --- Title header variants ---
78	
79	const WithTitleExample = ({ size, titleStyle }: { size: ZimmDrawerSize; titleStyle?: 'large' | 'small' }) => {
80	  const [isOpen, setIsOpen] = useState(true);
81	  return (
82	    <ZimmDrawer isOpen={isOpen} onClose={() => setIsOpen(false)} size={size} title="SIGN IN" titleStyle={titleStyle}>
83	      <chakra.p padding="var(--zimm-scale-xl)">Drawer body content.</chakra.p>
84	    </ZimmDrawer>
85	  );
86	};
87	
88	/** Inline header row: title on the left, close button on the right — Figma Heading (Large) style. */
89	export const WithTitleLarge: Story = {
90	  render: () => <WithTitleExample size="large" titleStyle="large" />,
91	  play: async () => {
92	    // Portal renders outside canvasElement — testing.md §Layer-2 exception (see Large's play).
93	    const doc = within(document.body);
94	    // Queried by computed accessible name rather than a specific aria-* attribute: ZimmDrawer's
95	    // custom ZimmDrawerContent sets aria-labelledby to the visible title span's id for the title
96	    // case (see index.tsx's own comment on why aria-label isn't needed here) — this asserts the
97	    // real outcome without pinning the test to which mechanism produces it.
98	    const dialog = await doc.findByRole('dialog', { name: 'SIGN IN' });
99	    await expect(dialog).toBeInTheDocument();
100	    await expect(doc.getByText('SIGN IN')).toBeInTheDocument();
101	  },
102	};
103	
104	/** Inline header with body2Strong (14px bold) title — Figma Heading (Small) / textStyle="body2Strong". */
105	export const WithTitleSmallStyle: Story = {
106	  render: () => <WithTitleExample size="large" titleStyle="small" />,
107	};
108	
109	/** Small-width drawer with inline title header. */
110	export const WithTitleSmallDrawer: Story = {
111	  render: () => <WithTitleExample size="small" titleStyle="large" />,
112	};
113	
114	/** Title close button dismisses the drawer. */
115	export const TitleCloseButtonClosesTheDrawer: Story = {
116	  render: () => <WithTitleExample size="large" />,
117	  play: async () => {
118	    // Portal renders outside canvasElement — testing.md §Layer-2 exception (see Large's play).
119	    const doc = within(document.body);
120	    const dialog = await doc.findByRole('dialog');
121	    await expect(dialog).toBeInTheDocument();
122	
123	    await userEvent.click(doc.getByRole('button', { name: /close/i }));
124	
125	    await waitForElementToBeRemoved(dialog);
126	  },
127	};
128

1	import React, { useState } from 'react';
2	import type { Meta, StoryObj } from '@storybook/react-webpack5';
3	import { chakra } from '@chakra-ui/react';
4	import { expect, userEvent, within } from 'storybook/test';
5	import { ZimmFiltersDrawerContent } from './index';
6	import type { FilterFacetGroup } from './index';
7	import { ZimmDrawer } from 'app/components/ui-kits/atoms/zimmDrawer';
8	import { ZimmButton } from 'app/components/ui-kits/atoms/zimmButton';
9	
10	const meta: Meta<typeof ZimmFiltersDrawerContent> = {
11	  title: 'Commerce/ZimmFiltersDrawerContent',
12	  component: ZimmFiltersDrawerContent,
13	};
14	export default meta;
15	type Story = StoryObj<typeof ZimmFiltersDrawerContent>;
16	
17	// -----------------------------------------------------------------------------------------
18	// Placeholder facet content
19	//
20	// Every one of these is a stand-in for the real facet UI SFCC-108 will build. Using plain
21	// list markup rather than the eventual radio/checkbox/swatch components keeps this story
22	// file honest about what it is *actually* proving — the drawer-content organism's structural
23	// behaviour — without pretending to preview the finished visual design.
24	// -----------------------------------------------------------------------------------------
25	
