27	  <chakra.ul listStyleType="none" padding={0} margin={0}>
28	    {['READY TO WEAR', 'SWIM & RESORT', 'NEW THIS WEEK', 'ACCESSORIES', 'SHOES', 'JEWELLERY', 'DRESSES', 'DENIM'].map(
