81	
82	const SizePlaceholder = (
83	  <chakra.div>
84	    <chakra.div marginBottom="var(--zimm-scale-s)">
85	      <chakra.div textStyle="body2Strong" textTransform="uppercase" marginBottom="var(--zimm-scale-2xs)">
86	        Clothing
87	      </chakra.div>
